INSERT INTO dms_finance_refund
(order_id, order_no, refund_no, refund_amount, product_refund_amount, freight_refund_amount,
 refund_quantity, clawback_bonus, reason, operator_id, operator_name, refund_time)
SELECT #{refund.orderId}, #{refund.orderNo}, #{refund.refundNo}, #{refund.refundAmount},
 #{refund.productRefundAmount}, #{refund.freightRefundAmount}, #{refund.refundQuantity},
 #{refund.clawbackBonus}, #{refund.reason}, #{refund.operatorId}, #{refund.operatorName}, #{refund.refundTime}
FROM dms_shop_order scoped_order
WHERE scoped_order.id = #{refund.orderId}
  AND COALESCE(scoped_order.tenant_id, 1) = #{tenantId}
